-- Howling Fjord: combat SmartAI for 15 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (23670,23725,23777,23967,24009,24010,24016,24098,24100,24102,24161,24162,24228,24335,24790) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (23670,23725,23777,23967,24009,24010,24016,24098,24100,24102,24161,24162,24228,24335,24790);
DELETE FROM `creature_text` WHERE `entry` IN (23670,23967,24790);
