INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(23670, 0, 0, 'For Ymiron!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 1, 'I will break you!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 2, 'I''ll eat your heart!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 3, 'Look what''s come to play.', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 4, 'My life for Ymiron!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 5, 'You tiny creatures disgust me!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23670, 0, 6, 'Your race is a disease upon the world!', 12, 0, 100, 1, 0, 0, 'Winterskon Elder'),
(23967, 0, 0, 'Ahahaha! I must find the secrets!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 1, 'I don''t want to know anymore. Make me forget!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 2, 'When one studies and digs, one reveals the truth.', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 3, 'We''re safe; IT will never reach us here!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 4, 'The end is nigh! That Which Must Not Be Named is almost free!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 5, 'IT''s coming! HIDE!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 6, 'If only there were more time!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 7, 'Forgive me oh great one. I did not mean to learn the truth!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 8, 'The truth shall set you free. Like us, you will be with IT forever!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 9, 'Now that you know the truth, I can''t let you leave!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 10, 'It''ll all be over soon. Soon you will be in the embrace of That Which Must Not Be Named!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 11, 'Intruder! You were sent to destroy us!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 12, 'You cannot leave... IT mustn''t find us!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 13, 'If you''re here, then IT might be close behind!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 14, 'I will put an end to your life before you realize the horrible truth!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(23967, 0, 15, 'Now you''ll have to join us... permanently!', 12, 7, 100, 0, 0, 0, 'Deranged Explorer'),
(24790, 0, 0, 'Yarrrr!  If it''s me treasure yer lookin'' for... yer gonna have to fight for it!', 12, 0, 100, 1, 0, 0, 'Black Conrad''s Ghost'),
(24790, 1, 1, 'Yarrrrr... dead again!', 12, 0, 100, 0, 0, 0, 'Black Conrad''s Ghost');
